package install

import (
	"context"
	"crypto/ed25519"
	"fmt"
	"time"

	a "clawreef/internal/systembackupkekadapter"
	reg "clawreef/internal/systembackupkekregistry"
)

// Record identities are generated by this owner from the original operation
// and exact material identity. There is no caller-selected source/record/hash.
func (b *IssuedOriginalAdoptionControls) controlSource(partition reg.Partition, kind string) reg.SourceRecord {
	id := originalObjectSHA(struct{ Operation, Material, Partition, Kind string }{b.hold.set.owner.operation, b.material.SHA256, string(partition), kind})
	return reg.SourceRecord{SourceID: "original-owner:" + id, RecordID: fmt.Sprintf("sev_%s-%s-%s-%s-%s", id[:8], id[8:12], id[12:16], id[16:20], id[20:32]), RecordVersion: "original-adoption.v1"}
}

func (b *IssuedOriginalAdoptionControls) recordRevision() string {
	return originalObjectSHA(struct{ Operation, SQL, Snapshot, Fence, Material string }{b.hold.set.owner.operation, b.coverage.sqlMetadata.revision, b.coverage.sourceSet.snapshotRevision, b.coverage.sourceSet.fenceRevision, b.material.SHA256})
}

// These are private owner projections of genuine held sources. Do not marshal
// private source structs: that would silently sign an empty JSON object.
func (b *IssuedOriginalAdoptionControls) actualOwnerObservation(kind string) (any, error) {
	s := b.coverage.sourceSet
	switch kind {
	case "immutable_external_snapshot":
		type root struct {
			Node, Path, Anchor, Boot string
			Binding                  any
			ObservedAt, Until        time.Time
		}
		roots := make([]root, 0, len(s.heldFilesystem))
		for _, r := range s.heldFilesystem {
			if r == nil || r.origin != r || r.failed || r.hold != b.hold || r.prep != b.prep || r.proof == nil || r.node == nil || !time.Now().Before(r.until) {
				return nil, ErrInstall
			}
			roots = append(roots, root{r.binding.Node, r.path, r.anchor, r.boot, r.binding, r.observedAt, r.until})
		}
		// A finite source owner has positively selected the FS-only branch and C
		// has read each selected directory to EOF while the original hold persists.
		// This is not a live external LIST, absent scanner or caller NoS3 assertion.
		return struct {
			Version, SQL, Consumers, Snapshot string
			Roots                             []root
		}{"original-held-finite-history-snapshot.v1", s.metadata.revision, s.resolved.revision, s.snapshotRevision, roots}, nil
	case "original_writer_fence":
		if s.originalNative == nil || s.originalNative.set != b.hold.set || s.originalNative.digest == "" {
			return nil, ErrInstall
		}
		return struct {
			Version, Operation, Inventory, Native, Fence string
			Reservation                                  any
			Until                                        time.Time
		}{"original-held-writer-fence.v1", b.hold.set.owner.operation, b.hold.set.inventorySHA, s.originalNative.digest, s.fenceRevision, b.prep.reservation, s.nativeUntil}, nil
	case "historical_backfill":
		// This implementation is deliberately the genuine classified empty branch.
		// The complete original SQL and C history classifications must both remain
		// empty. Nonempty/unclassified history requires its own real backfill owner.
		refs := b.coverage.history.references()
		if refs == nil || len(refs) != 0 || b.snapshot.References == nil || len(b.snapshot.References) != 0 {
			return nil, ErrInstall
		}
		return struct {
			Version, SQL, Consumers, Snapshot string
			History, Registry                 []reg.Reference
		}{"original-classified-empty-backfill.v1", s.metadata.revision, s.resolved.revision, s.snapshotRevision, refs, b.snapshot.References}, nil
	}
	return nil, ErrInstall
}

func originalAdoptionSigningKey(key ed25519.PrivateKey) bool {
	if len(key) != ed25519.PrivateKeySize {
		return false
	}
	canonical := ed25519.NewKeyFromSeed(key[:ed25519.SeedSize])
	defer clear(canonical)
	var changed byte
	for i := range canonical {
		changed |= canonical[i] ^ key[i]
	}
	return changed == 0
}

// This method is private to the actual source-owning batch. Neither facts,
// Passed, observation hashes, revisions nor expiry are parameters.
func (b *IssuedOriginalAdoptionControls) signActualOriginalOwnerWitness(ctx context.Context, partition reg.Partition, kind string, key ed25519.PrivateKey) (a.SignedCoverageOwnerRecord, a.CoverageWitnessPin, error) {
	fail := func() (a.SignedCoverageOwnerRecord, a.CoverageWitnessPin, error) {
		return a.SignedCoverageOwnerRecord{}, a.CoverageWitnessPin{}, ErrInstall
	}
	if b == nil || b.origin != b || b.failed || b.coverage == nil || b.coverage.sourceSet == nil || !consumerSameContext(ctx, b.ctx) || !originalAdoptionSigningKey(key) || !b.coverage.sourceSet.local(ctx, false) || !time.Now().Before(b.until) {
		return fail()
	}
	valid := false
	for _, p := range originalAdoptionPartitions {
		if partition == p {
			valid = true
		}
	}
	if !valid {
		return fail()
	}
	observation, err := b.actualOwnerObservation(kind)
	if err != nil {
		return fail()
	}
	scope := struct {
		Database                                            reg.DatabaseIdentity
		Installation, Operation, Partition, Kind, SourceSet string
	}{b.snapshot.Database, b.snapshot.InstallationID, b.hold.set.owner.operation, string(partition), kind, b.coverage.sourceSet.snapshotRevision}
	facts := a.CoverageWitnessFacts{Database: b.snapshot.Database, InstallationID: b.snapshot.InstallationID, Partition: partition, Kind: kind, ScopeSHA256: originalObjectSHA(scope), ObservationSHA256: originalObjectSHA(observation), SnapshotRevision: b.coverage.sourceSet.snapshotRevision, FenceRevision: b.coverage.sourceSet.fenceRevision}
	source := b.controlSource(partition, kind)
	source.ContentSHA256 = originalObjectSHA(facts)
	record := a.CoverageWitnessRecord{Facts: facts, Source: source, Revision: b.recordRevision(), NotBefore: b.snapshot.ObservedAt, Until: b.until}
	raw, err := originalIssuedJSON(record)
	if err != nil || len(raw) > 8192 {
		return fail()
	}
	signed := a.SignedCoverageOwnerRecord{Record: raw, Signature: ed25519.Sign(key, append([]byte(a.OriginalCoverageWitnessDomain), raw...))}
	pin := a.CoverageWitnessPin{CoverageOwnerPin: a.CoverageOwnerPin{Source: source, Issuer: append(ed25519.PublicKey(nil), key.Public().(ed25519.PublicKey)...)}, Partition: partition, Kind: kind, ScopeSHA256: facts.ScopeSHA256}
	return signed, pin, nil
}

// The fifth independent owner key attests exactly the sixteen issued source
// records. It cannot replace a missing witness or choose a replacement epoch.
func (b *IssuedOriginalAdoptionControls) signActualOriginalAdoption(ctx context.Context, key ed25519.PrivateKey) (a.SignedCoverageOwnerRecord, a.CoverageOwnerPin, error) {
	fail := func() (a.SignedCoverageOwnerRecord, a.CoverageOwnerPin, error) {
		return a.SignedCoverageOwnerRecord{}, a.CoverageOwnerPin{}, ErrInstall
	}
	if b == nil || b.origin != b || b.failed || b.coverage == nil || b.coverage.sourceSet == nil || !consumerSameContext(ctx, b.ctx) || !originalAdoptionSigningKey(key) || !b.coverage.sourceSet.local(ctx, false) || !originalAdoptionEmptyRegistry(b.prep, b.snapshot) || len(b.pins.Witnesses) != 16 || len(b.records) != 16 || !time.Now().Before(b.until) {
		return fail()
	}
	facts := a.CoverageAdoptionFacts{Database: b.snapshot.Database, InstallationID: b.snapshot.InstallationID, AdoptedEpoch: b.snapshot.Epoch + 1, Partitions: make([]a.CoveragePartitionAdoption, 0, 4)}
	for _, partition := range originalAdoptionPartitions {
		sources := map[string]reg.SourceRecord{}
		for _, pin := range b.pins.Witnesses {
			if pin.Partition == partition {
				if _, exists := sources[pin.Kind]; exists {
					return fail()
				}
				sources[pin.Kind] = pin.Source
			}
		}
		if len(sources) != 4 {
			return fail()
		}
		for _, kind := range originalAdoptionIssuerRoles[:4] {
			if sources[kind].RecordID == "" {
				return fail()
			}
		}
		facts.Partitions = append(facts.Partitions, a.CoveragePartitionAdoption{Partition: partition, SourceID: b.controlSource(partition, "partition").SourceID, SnapshotRevision: b.coverage.sourceSet.snapshotRevision, FenceRevision: b.coverage.sourceSet.fenceRevision, ReferenceCount: 0, ReferencesSHA256: originalObjectSHA(make([]reg.Reference, 0)), SQLCensus: sources["original_sql_census"], ImmutableExternalSnapshot: sources["immutable_external_snapshot"], WriterFence: sources["original_writer_fence"], HistoricalBackfill: sources["historical_backfill"]})
	}
	source := b.controlSource("", "adoption")
	source.ContentSHA256 = originalObjectSHA(facts)
	record := a.CoverageAdoptionRecord{Facts: facts, Source: source, Revision: b.recordRevision(), NotBefore: b.snapshot.ObservedAt, Until: b.until}
	raw, err := originalIssuedJSON(record)
	if err != nil || len(raw) > 8192 {
		return fail()
	}
	return a.SignedCoverageOwnerRecord{Record: raw, Signature: ed25519.Sign(key, append([]byte(a.OriginalCoverageDomain), raw...))}, a.CoverageOwnerPin{Source: source, Issuer: append(ed25519.PublicKey(nil), key.Public().(ed25519.PublicKey)...)}, nil
}
